questionvariables.text:
/* Randomly select the angle of elevation */
theta: 25+5*rand(7);

/* Randomly select the horizontal distance in metres */
distance: 15+5*rand(8);

/* Convert the angle to radians */
theta_rad: theta*%pi/180;

/* Calculate the building height */
height: distance*tan(theta_rad);

/* Round the answer to 1 decimal place */
ta1: round(height*10)/10;
